  ('Alaska Housing Finance Corporation', 'energy', 'AHFC''s New Home Construction Rebate applies to new single-family residential 1- to 4-unit construction homes that achieve a 5-Star Plus or higher energy rating.', 'https://www.alaskahousingenergy.us/applicants', 'Please note that the Home Electrification and Appliance Rebate Program HER 50121 & HEAR 50122 has not launched in Alaska,  so this is the only rebate available at this time (https://www.ahfc.us/efficiency/programs-for-homeowners/alaska-residential-energy-rebates)', 'Alaska', 'AK', 'state', 'Working', null),
  ('Recycling Programs', 'recycling', 'This website lists community recycling programs.', 'https://dec.alaska.gov/eh/solid-waste/reduce-reuse-recycle/', 'See link below.', 'Alaska', 'AK', 'state', 'Blocked', null),
  ('Arizona Recycling Locator', 'recycling', 'Use this app to find information on e-waste, household hazardous waste (HHW), and general recycling in your community.', 'https://experience.arcgis.com/experience/6ab7b53043e64f4f917d76169e303ec6', 'Access this app via the link below.', 'Arizona', 'AZ', 'state', 'Working', null),
  ('Plastic Film Recycling', 'recycling', 'Use this tool to find a recycling drop off center for flexible plastic film near you.', 'https://plasticfilmrecycling.org/', 'See link below.', 'Arizona', 'AZ', 'state', 'Working', null),
  ('Recycling Toolkit', 'recycling', 'The Recycling Toolkit is a guide to building recycling programs in Arizona, created by ADEQ in collaboration with the Arizona Recycling Coalition and Keep Arizona Beautiful.', 'https://azdeq.gov/RecyclingToolkit', 'See link below.', 'Arizona', 'AZ', 'state', 'Blocked', null),
  ('The Arkansas Recycling Equipment Tax Credit Program', 'recycling', 'The tax credit reduces a participant''s Arkansas income tax amount due by 30 percent of the amount paid for eligible recycling equipment and installation.', 'https://www.adeq.state.ar.us/poa/enterprise-services/market/tax-credit.aspx', 'See link below.', 'Arkansas', 'AR', 'state', 'Redirect', null),
  ('Where to Recycle', 'recycling', 'This website explains where to recycle various materials in California.', 'https://calrecycle.ca.gov/Recycle/', 'See link below.', 'California', 'CA', 'state', 'Working', null),
  ('Colorado Home Energy Rebate Program', 'energy', 'The Colorado Home Energy Rebate Program will provide rebates to eligible Coloradans for high-efficiency electric appliances and whole-home energy efficiency upgrades. These rebates will lower upfront costs for projects that reduce energy use and make homes healthier and more comfortable.', 'https://energyoffice.colorado.gov/home-energy-rebates', 'See link below.', 'Colorado', 'CO', 'state', 'Working', null),
  ('Tax Credits & Incentives', 'energy', 'Households earning up to 150% of the area median income can receive instant rebates through the HEAR Program when switching to electric systems and improving home insulation and efficiency.', 'https://energysmartcolorado.org/tax-credits-incentives/', 'See link below.', 'Colorado', 'CO', 'state', 'Working', null),
  ('UPGRADE & SAVE - CT Energy Efficiency and Safety Rebate', 'energy', 'The UPGRADE & SAVE - CT Energy Efficiency and Safety Rebate offers Connecticut homeowners up to $1,000 when they install a new higher-efficiency oil-fired furnace or boiler.', 'https://upgradeandsavect.com/', 'See link below.', 'Connecticut', 'CT', 'state', 'Working', null),
  ('Energize Connecticut', 'energy', 'Energize Connecticut (Energize CT) is a statewide initiative backed by Connecticut’s utilities and state agencies to help residents and businesses reduce their energy use and lower utility costs. Energize CT programs encompass a range of initiatives, including energy-efficient rebates, low-cost energy audits, business incentives, and electricity rate comparisons.', 'https://www.energizect.com/rebates-and-incentives', 'See link below.', 'Connecticut', 'CT', 'state', 'Blocked', null),
  ('Connecticut energy rebates guide', 'energy', 'This is an easy to understand guide to local rebates that can help you save money on comfort and energy upgrades.', 'https://sealed.com/resources/ct-energy-rebates/', 'See link below.', 'Connecticut', 'CT', 'state', 'Redirect', null),
  ('Recycling Program FAQ''s', 'recycling', 'This page provides general recycling FAQs for Connecticut.', 'https://portal.ct.gov/DEEP/Reduce-Reuse-Recycle/FAQs---Recycling-Program', 'See link below.', 'Connecticut', 'CT', 'state', 'Working', null),
  ('Connecticut Low Income Household Water Assistance Program (LIHWAP)', 'water', 'If you receive benefits from the Connecticut Energy Assistance Program, SNAP, TFA, SSI, State Supplement, or Refugee Cash, then you likely meet the income requirements to qualify for water assistance.', 'https://portal.ct.gov/DSS/Highlights/Low-Income-Household-Water-Assistance-Program-Coming-to-CT/How-To-Apply?language=en_US', 'See link below.', 'Connecticut', 'CT', 'state', 'Working', null),
  ('Energize Delaware', 'energy', 'The Home Efficiency Rebate Program and Home Electrification and Appliance Rebate Program, which are expected to launch once funding is received later this year, are designed to help Delawareans reduce home energy costs.', 'https://energizedelaware.org/residential/', 'See link below.', 'Delaware', 'DE', 'state', 'Working', null),
  ('Home Energy Rebate Programs', 'energy', 'Save on energy-efficient upgrades with rebates, assistance programs, and solar incentives.', 'https://energizedelaware.org/residential/', 'See link below.', 'Delaware', 'DE', 'state', 'Working', null),
  ('Delaware Solar Incentives, Tax Credits And Rebates', 'energy', 'This page provides a table featuring five solar panel rebates.', 'https://www.forbes.com/home-improvement/solar/delaware-solar-incentives/', 'See link below.', 'Delaware', 'DE', 'state', 'Blocked', null),
  ('Recyclopedia: What Can I Recycle in Delaware', 'recycling', 'Use the Recyclopedia search tool to find out if something is acceptable to recycle at home, if you need to drop it off, or if it is trash.', 'https://dnrec.delaware.gov/waste-hazardous/recycling/what/#/locationSelection', 'See link below.', 'Delaware', 'DE', 'state', 'Working', null),
  ('Florida Energy Saver program', 'energy', 'The Home Electrification and Appliance Rebates (HEAR) and Home Efficiency Rebates (HOMES) programs are expected to launch in the future. If you are interested in participating, please register or sign in if you already have an account.', 'https://floridaenergysaverprogram.fdacs.gov/en-US', 'If you are interested in participating, please register or sign in if you already have an account. See link below for more information.', 'Florida', 'FL', 'state', 'Working', null),
  ('Florida Recycling', 'recycling', 'This page provides general information about recycling in Florida. Find information about resources at the bottom of the page.', 'https://floridadep.gov/waste/waste-reduction/content/recycling', 'Find information about resources at the bottom of the page via the link below.', 'Florida', 'FL', 'state', 'Working', null),
  ('Georgia''s Home Energy Rebates', 'energy', 'Georgia’s Home Energy Rebates provide households with incentives on the purchase and installation of electric appliances, insulation, air sealing, HVAC, and other home improvement measures. Eligible households can get up to $16,000 in savings depending on their household income and/or expected energy savings.', 'https://energyrebates.georgia.gov/', 'See link below.', 'Georgia', 'GA', 'state', 'Working', null),
