  ('Environmental Quality Incentives Program', 'water', 'The Environmental Quality Incentives Program (EQIP) provides financial and technical assistance to agricultural producers and non-industrial forest managers to conserve natural resources while strengthening their operations.', 'https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/indiana/environmental-quality', 'See link below.', 'Indiana', 'IN', 'state', 'Working', null),
