  ('Residential Energy Efficiency and Electrification Programs', 'energy', 'The home energy rebates will help households save money on energy bills, upgrade to clean energy equipment, and improve energy efficiency.', 'https://opportunityiowa.gov/community/energy/grants-funding/residential-energy-efficiency-programs', 'See link below.', 'Iowa', 'IA', 'state', 'Working', null),
  ('Multifamily Energy Audit Program', 'energy', 'The Iowa Economic Development Authority (IEDA) provides federal grant funds for the completion of energy audits and the improvement of lighting energy efficiency at multifamily housing properties.', 'https://opportunityiowa.gov/community/energy/grants-funding/multifamily-energy-audit-program', 'See link below.', 'Iowa', 'IA', 'state', 'Working', null),
  ('Soil Conservation and Water Quality Cost Share Assistance', 'water', 'Your local Soil and Water Conservation District administers numerous programs supported by the Iowa Department of Agriculture and Land Stewardship, which can provide partial financial assistance to address farmers’ and landowners’ soil conservation and water quality concern.', 'https://costshare.iowaagriculture.gov/', 'See link below.', 'Iowa', 'IA', 'state', 'Working', null),
