  ('Individual Water and Wastewater Grants', 'water', 'Applications for this program are accepted year-round. Please apply through your local Rural Development office.', 'https://www.rd.usda.gov/programs-services/single-family-housing-programs/individual-water-wastewater-grants/ks', 'Please apply through your local Rural Development office.', 'Kansas', 'KS', 'state', 'Blocked', null),
  ('Natural Resources Conservation Service', 'water', 'The Natural Resources Conservation Service offers technical and financial assistance to help farmers, ranchers, and landowners.', 'https://www.kacd.net/usda-nrcs.cfm', 'See link below.', 'Kansas', 'KS', 'state', 'Working', null),
  ('Regenerative Ag and Soil Health Initiatives', 'water', 'To learn more about these programs, producers can reach out to their local Conservation District.', 'https://www.kacd.net/advancing-markets-for-producers.cfm', 'See link below.', 'Kansas', 'KS', 'state', 'Working', null),
  ('Kansas Reservoir Protection Initiative', 'water', 'KRPI provides financial assistance to landowners for the implementation of sediment-reducing practices on lands upstream of multiple reservoirs.', 'https://www.kacd.net/kansas-reservoir-protection-initiative.cfm', 'See link below.', 'Kansas', 'KS', 'state', 'Working', null),
  ('Kansas WRAPS (Watershed Restoration and Protection Strategies)', 'water', 'The Kansas WRAPS process offers a framework that engages citizens and other stakeholders in a teamwork environment aimed at protecting and restoring Kansas watersheds.', 'https://www.kacd.net/kansas-wraps.cfm', 'See link below.', 'Kansas', 'KS', 'state', 'Working', null),
  ('Specialty Crops and Urban Ag', 'water', 'Districts are able to deliver technical and financial assistance to a broad spectrum of producers, from aspiring to experienced, small to medium-scale, in the diverse urban, suburban, and rural communities across Kansas.', 'https://www.kacd.net/specialty-crops-and-urban-ag.cfm', 'See link below.', 'Kansas', 'KS', 'state', 'Working', null),
  ('State Cost-Share Program', 'water', 'The Kansas Department of Agriculture, Division of Conservation (DOC), works to protect and enhance Kansas’ natural resources through programs designed to assist local conservation district boards and individuals in conserving the state’s renewable resources.', 'https://www.kacd.net/state-cost-share.cfm', 'See link below.', 'Kansas', 'KS', 'state', 'Working', null),
