  ('Efficiency Maine', 'energy', 'Click on "rebates" and "solutions" for home energy, water, and appliance rebates. Residents can also check the website’s "Green Bank" page. Efficiency Maine also offers home energy loans to help homeowners pay for qualifying energy upgrades.', 'https://www.efficiencymaine.com/', 'Click on "rebates" and "solutions" for home energy, water, and appliance rebates. Residents can also check the website’s "Green Bank" page.', 'Maine', 'ME', 'state', 'Working', null),
  ('MaineHousing programs', 'energy', 'This program can help you pay for heating your home, electric bills, and energy improvements like new insulation or heating systems.', 'https://www.mainehousing.org/programs-services/energy', 'See link below.', 'Maine', 'ME', 'state', 'Working', null),
  ('Maine Laws and Incentives', 'transportation', 'EV rebates (that’s it). Utilities/private entities. Check Maine Clean Communities.', 'https://afdc.energy.gov/laws/state_summary?state=ME', 'Check Maine Clean Communities via link below.', 'Maine', 'ME', 'state', 'Server Error', null),
  ('EmPOWER program', 'energy', 'Utilities must have incentives to help individuals switch from fossil fuel-powered heating and appliances to efficient, electric alternatives.', 'https://energy.maryland.gov/pages/facts/empower.aspx', 'See link below.', 'Maryland', 'MD', 'state', 'Working', null),
  ('Maryland Energy Administration', 'energy', 'Visit the Maryland Energy Administration website and look under grants and incentives for residential programs. The page includes options for storage, solar, geothermal rebates, community solar, clean energy rebates, energy equity grants, and energy storage tax credits.', 'https://energy.maryland.gov/Pages/all-incentives.aspx', 'Visit the Maryland Energy Administration website and look under ''Grants, Loans, Rebates, and Other Incentives'' for residential programs.', 'Maryland', 'MD', 'state', 'Working', null),
  ('Maryland Laws and Incentives', 'transportation', 'This page lists EV and fuel cell vehicle tax credits, EV charger rebates, HOV lane exemptions, and other related incentives, including utility and private entity resources.', 'https://afdc.energy.gov/laws/state_summary?state=MD', 'See link below.', 'Maryland', 'MD', 'state', 'Server Error', null),
  ('Titling - Excise Tax Credit for Plug-in Electric Vehicles', 'transportation', 'Excise Tax Credit for Plug-in Electric or Fuel Cell Vehicles', 'https://mva.maryland.gov/your-mva-guide/businesses/bulletins-businesses/excise-tax-credit-plug-electric-or-fuel-cell-vehicles-no-more-fiscal-year-2026-funding', 'The Motor Vehicle Administration (MVA) reports that the Fiscal Year 2026 funds for the EV excise tax credit are depleted. They will, however, continue to accept applications and place applicants on a waiting list.', 'Maryland', 'MD', 'state', 'Working', null),
  ('Energy Rebates & Incentives', 'energy', 'List of federal and state rebates for Minnesota.', 'https://www.mass.gov/guides/massachusetts-energy-rebates-incentives', 'See link below.', 'Massachusetts', 'MA', 'state', 'Redirect', null),
  ('home energy efficiency tax credits', 'energy', 'You can sign up for the "Consumer Announcements" newsletter for information on rebates, grants, and incentives. Scroll down to the "Consumers" section for additional programs. The page also includes EV information and renter resources, although EV rebates are currently unavailable.', 'https://www.michiganlcv.org/save-money-with-home-energy-efficiency-tax-credits/', 'Sign up for the "Consumer Announcements" newsletter for information on rebates, grants, and incentives. Scroll down to the "Consumers" section for additional programs.', 'Michigan', 'MI', 'state', 'Working', null),
  ('State of Michigan
Community EV Toolkit', 'transportation', 'The State of Michigan Community EV Toolkit gives local communities and stakeholders quick access to key data and background information, the current status of EV registration, infrastructure and deployment, community zoning and planning ordinances, community fleet electrification, funding opportunities, and local best practices.', 'https://southeast-michigan-ev-resource-kit-and-planning-hub-semcog.hub.arcgis.com/', 'See link below.', 'Michigan', 'MI', 'state', 'Working', null),
  ('Michigan Laws and Incentives', 'transportation', 'This page lists EV toll lane credits and EV rebates. Some utility information may be outdated, especially at the local level, so it is best to check your local utility website.', 'https://afdc.energy.gov/laws/all?state=MI', 'See link below.', 'Michigan', 'MI', 'state', 'Working', null),
  ('Save Energy Minnesota', 'energy', 'This provides bill help for HEAP (or LIHEAP).', 'https://mn.gov/commerce/energy/consumer/energy-programs/save-energy-mn.jsp', 'See link below.', 'Minnesota', 'MN', 'state', 'Working', null),
  ('New Energy Programs', 'energy', 'Save Energy Minnesota combines state and federal rebate programs to support energy-efficient home improvements. It offers several rebate options to help make clean energy upgrades more affordable for communities and residents across Minnesota.', 'https://mn.gov/commerce/energy/consumer/energy-programs/save-energy-mn.jsp', 'Current update (6/12/2026): Save Energy Minnesota has not launched yet. Minnesota is waiting for formal approval from US Department of Energy (DOE) to launch the program. See link below', 'Minnesota', 'MN', 'state', 'Working', null),
  ('Free Water Conservation Kit', 'water', '', 'https://www.minnesotaenergyresources.com/savings/water-conservation', 'See link below.', 'Minnesota', 'MN', 'state', 'Working', null),
  ('Minnesota Laws and Incentives', 'transportation', '', 'https://afdc.energy.gov/laws/all?state=MN', 'See link below.', 'Minnesota', 'MN', 'state', 'Working', null),
  ('Office of Energy', 'energy', 'This page explains how to find an energy auditor. It does not provide financial assistance, but an audit can help identify cost effective measures.', 'https://mississippi.org/community-resources/office-of-energy/', 'See link below.', 'Mississippi', 'MS', 'state', 'Working', null),
  ('Department of Revernue', 'energy', '', 'https://dor.mo.gov/taxation/business/tax-types/sales-use/holidays/show-me-green/', 'See link below.', 'Missouri', 'MO', 'state', 'Working', null),
  ('Inflation Reduction Act (IRA) Home Energy Rebates Programs', 'energy', 'The Missouri Department of Natural Resources held public meetings to discuss the rebates and planned state programs. On Nov. 22, 2024, the department submitted the state’s application to DOE to receive these funds. Please note that details about rebate eligibility and how to apply are not finalized at this time. The department cannot provide an estimate as to when rebates will be available to the public. The rebates may not be made available until 2027 at the earliest and potentially as late as 2028.', 'https://dnr.mo.gov/energy/what-were-doing/inflation-reduction-act-home-energy-rebates-programs', 'Rebates not available yet. See link below for more information.', 'Missouri', 'MO', 'state', 'Redirect', null),
  ('Energy Financial Assistance Opportunities', 'energy', 'In the website, tap on interested energy programs, which link to more detailed information.', 'https://dnr.mo.gov/energy/financial-assistance-opportunities', 'On the website, tap on interested energy programs, which link to more detailed information.', 'Missouri', 'MO', 'state', 'Working', null),
