  ('WasteNet Program-Recycle', 'recycling', 'Tap on the categories of recyclables that interest you to access local drop off sites and contact information.', 'https://www.wastenotproject.org/recycle/', 'Tap on the categories of recyclables that interest you to access local drop off sites and contact information.', 'Montana', 'MT', 'state', 'Working', null),
  ('Recycle Montana', 'recycling', 'This page explains composting grant applications and criteria.', 'https://www.recyclemontana.org/grants/recycling-project-of-your-choice-grant', 'See link below.', 'Montana', 'MT', 'state', 'Working', null),
  ('Montana Watershed Coordination Council Watershed Fund', 'water', '', 'https://www.mtwatersheds.org/support/mwcc-grants/', 'See link below.', 'Montana', 'MT', 'state', 'Working', null),
  ('Montana Clean Water', 'water', 'This link provides access to documents available for protecting your right to access clean water.', 'https://www.montanacleanwater.com/forms-documents', 'See link below.', 'Montana', 'MT', 'state', 'Working', null),
  ('Montana Water Funding sources', 'water', 'This page links to agencies that provide funding for community development needs or bond financing for eligible governments. Tap on the targeted community or government funds to view contact information and links to fund websites.', 'https://www.montanawater.org/links-things/funding-sources/', 'Tap on the targeted community or government funds to view contact information and links to fund websites.', 'Montana', 'MT', 'state', 'Working', null),
  ('NC Clean Energy Technology Center Net Metering', 'energy', 'Nebraska offers net metering for residential renewable systems (solar, wind, etc.) up to 25 kW, crediting excess energy sent to the grid at the retail rate, though policies can vary by utility and focus is on bill reduction rather than cash payments, with potential for carryover credits.', 'https://programs.dsireusa.org/system/program/detail/3386', 'See link below.', 'Nebraska', 'NE', 'state', 'Working', null),
  ('The Waste Reduction and Recycling Incentive Grants Fund', 'recycling', 'The Waste Reduction and Recycling Incentive Grants Fund provides grants to support integrated waste management programs and projects. Application links are provided in blue below the grant funding section.', 'https://dee.nebraska.gov/land-waste/landfill-disposal-fee-rebate-program/litter-waste-reduction-and-recycling-incentive-grants', 'Application links are provided in blue below the grant funding section.', 'Nebraska', 'NE', 'state', 'Redirect', null),
  ('Recycling Equipment Grant (REG) Program', 'recycling', 'The Nebraska Recycling Council administers the Recycling Equipment Grant Program with funding from the Nebraska Environmental Trust. Scroll down to the blue "Apply Today" button and complete the Adobe fillable PDF application.', 'https://nrcne.org/recycling-equipment-grants/', 'Scroll down to the blue "Apply Today" button and complete the Adobe fillable PDF application.', 'Nebraska', 'NE', 'state', 'Working', null),
  ('The Nebraska Clean Water State Revolving Loan Fund (CWSRF) program', 'water', 'The Nebraska Clean Water State Revolving Loan Fund provides low interest loans and small community matching grants to municipalities for wastewater treatment and sanitary sewer projects. Residents can contact the program at 402-471-4200 for guidance through the planning process.', 'https://dee.nebraska.gov/aid/water-loans-grants-rebates/clean-water-state-revolving-loan-fund-wastewater-treatment-facilities-and-sanitary-sewer-collection-systems', 'Residents can contact the program at 402-471-4200 for guidance through the planning process.', 'Nebraska', 'NE', 'state', 'Redirect', null),
  ('Alternative Fuels Data Center State Incentives', 'transportation', 'Under the state incentives section, tax credit and tax refund resources are listed.', 'https://afdc.energy.gov/laws/state_summary?state=NE', 'View the ''State Incentives'' section for information.', 'Nebraska', 'NE', 'state', 'Working', null),
  ('The Clean Energy Plan', 'energy', 'The Clean Energy Plan provides financial incentives to Nevada residents, businesses, schools, and nonprofits for clean energy and energy efficiency improvements. Enter your household information and press "View Results" to see the available funding.', 'https://www.nevadaconservationleague.org/clean-energy-plan/', 'Enter your household information and press "View Results" to see the available funding.', 'Nevada', 'NV', 'state', 'Working', null),
  ('Free Nevada Solar Incentives', 'energy', 'This page explains Nevada solar incentives. To apply for free solar panel installation, click "Click Here to Sign Up for Free Solar Panel Installation," complete the State Solar Registry, and submit the form. To apply for the federal solar tax credit, scroll to the section on how to claim the credit and follow the listed steps.', 'https://nevada.statesolar.org/', 'To apply for free solar panel installation, click "Click Here to Sign Up for Free Solar Panel Installation," complete the State Solar Registry, and submit the form. To apply for the federal solar tax credit, scroll to the section on how to claim the credit and follow the listed steps.', 'Nevada', 'NV', 'state', 'Working', null),
  ('Renewable Energy Tax Abatements', 'energy', 'Renewable Energy Tax Abatements award partial sales and use tax abatements and partial property tax abatements to eligible renewable energy facilities. The application steps and timeline are listed under the Renewable Energy Tax Abatement Application section.', 'https://www.energy.nv.gov/programs/renewable-energy-tax-abatement-reta-program/', 'The application steps and timeline are listed under the Renewable Energy Tax Abatement Application section.', 'Nevada', 'NV', 'state', 'Working', null),
