  ('Alternative Fuels Data Center State Incentives', 'transportation', 'The Alternative Fuels Data Center lists Nevada incentives, including exemptions from emission testing requirements for alternative fuel vehicles.', 'https://afdc.energy.gov/laws/all?state=NV', 'See link below.', 'Nevada', 'NV', 'state', 'Working', null),
  ('Refrigerator & Freezer Recycling', 'recycling', 'Recycling a refrigerator or freezer may qualify for a $75 rebate. Tap "Get Started" and fill in your information.', 'https://nhsaves.com/residential/refrigerator-and-freezer-recycling/', 'Tap "Get Started" and fill in your information on the site.', 'New Hampshire', 'NH', 'state', 'Working', null),
  ('NHSaves', 'energy', 'Your NHSaves utility partners offer a wide variety of rebates on the products and technologies that help New Hampshire residents save energy.', 'https://nhsaves.com/rebates-services-appliances/', 'See link below.', 'New Hampshire', 'NH', 'state', 'Blocked', null),
  ('The PFAS Removal Rebate Program for Private Wells', 'water', 'The PFAS Removal Rebate Program for Private Wells provides rebates to private residential well owners of up to $5,000 for the installation of a treatment system designed to remove per- and polyfluoroalkyl substances (PFAS) or up to $10,000 for a service connection to a public water system.', 'https://www.pfas.des.nh.gov/funding/pfas-removal-rebate-program-private-wells', 'See link below.', 'New Hampshire', 'NH', 'state', 'Working', null),
